from collections import deque

def topo_sort(tasks: dict[str, list[str]]) -> list[str] | None:
    adj = {task: [] for task in tasks}
    in_degree = {task: 0 for task in tasks}

    for task, deps in tasks.items():
        for dep in deps:
            if dep not in adj:
                return None
            adj[dep].append(task)
            in_degree[task] += 1

    queue = deque([task for task in tasks if in_degree[task] == 0])
    result = []

    while queue:
        current = queue.popleft()
        result.append(current)

        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return None if len(result) != len(tasks) else result

def critical_path(tasks: dict[str, tuple[int, list[str]]]) -> int | None:
    # Check for cycles first (same as topo_sort)
    adj = {task: [] for task in tasks}
    in_degree = {task: 0 for task in tasks}

    for task, deps in tasks.items():
        duration, _ = deps
        for dep in deps[1]:
            if dep not in adj:
                return None
            adj[dep].append(task)
            in_degree[task] += 1

    queue = deque([task for task in tasks if in_degree[task] == 0])
    topo_order = []
    while queue:
        current = queue.popleft()
        topo_order.append(current)

        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topo_order) != len(tasks):
        return None

    # Calculate durations along the critical path
    duration = {task: tasks[task][0] for task in tasks}
    max_duration = 0
    current_max = 0

    for task in reversed(topo_order):
        current_max = max(current_max, duration.get(task, 0))
        if task in tasks:
            current_max += duration[task]
        max_duration = max(max_duration, current_max)

    return max_duration
